/* ─── Shared hook ────────────────────────────────────────────── */
function useInView(threshold = 0.12) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setInView(true); },
      { threshold }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return [ref, inView];
}

/* ─── Fade-in wrapper ────────────────────────────────────────── */
function Reveal({ children, delay = 0, style = {}, className = "" }) {
  const [ref, inView] = useInView();
  return (
    <div ref={ref} className={className} style={{
      opacity: inView ? 1 : 0,
      transform: inView ? "translateY(0)" : "translateY(24px)",
      transition: `opacity 0.75s cubic-bezier(.25,.46,.45,.94) ${delay}s,
                   transform 0.75s cubic-bezier(.25,.46,.45,.94) ${delay}s`,
      ...style,
    }}>{children}</div>
  );
}

/* ─── Section label ──────────────────────────────────────────── */
function SectionLabel({ text }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: "1.1rem" }}>
      <div style={{ width: 32, height: 1, background: C.blue, opacity: 0.7 }} />
      <span style={{
        color: C.blue, fontSize: 10, letterSpacing: "0.22em",
        textTransform: "uppercase", fontWeight: 600,
        fontFamily: "'DM Sans', system-ui, sans-serif",
      }}>{text}</span>
    </div>
  );
}

/* ─── Quote Modal ────────────────────────────────────────────── */
function QuoteModal({ preselected, onClose }) {
  const emptyForm = {
    name: "", phone: "", email: "",
    event: "", date: "", location: "",
    services: preselected ? [preselected] : [],
    other: "", message: "",
  };
  const [form, setForm]           = useState(emptyForm);
  const [submitted, setSubmitted] = useState(false);
  const [sending, setSending]     = useState(false);
  const overlayRef = useRef(null);

  // Update preselected if it changes (shouldn't normally, but safe)
  useEffect(() => {
    if (preselected && !form.services.includes(preselected)) {
      setForm(f => ({ ...f, services: [preselected] }));
    }
  }, [preselected]);

  // Close on Escape
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [onClose]);

  const toggleService = (s) => setForm(f => ({
    ...f,
    services: f.services.includes(s)
      ? f.services.filter(x => x !== s)
      : [...f.services, s],
  }));

  const handleSubmit = () => {
    if (!form.name.trim() || !form.phone.trim() || !form.email.trim()) {
      alert("Please fill in your name, phone number, and email address.");
      return;
    }
    setSending(true);
    // TODO: replace with EmailJS call
    setTimeout(() => { setSending(false); setSubmitted(true); }, 1100);
  };

  const field = {
    width: "100%", boxSizing: "border-box",
    background: "rgba(255,255,255,0.05)",
    border: "1px solid rgba(255,255,255,0.1)",
    borderRadius: 1, padding: "12px 14px",
    color: C.white, fontSize: "0.88rem",
    outline: "none", fontFamily: "'DM Sans', system-ui, sans-serif",
    fontWeight: 300, transition: "border-color 0.25s",
  };
  const fi = (e) => { e.target.style.borderColor = C.blue; };
  const fo = (e) => { e.target.style.borderColor = "rgba(255,255,255,0.1)"; };

  return (
    <div
      ref={overlayRef}
      onClick={(e) => { if (e.target === overlayRef.current) onClose(); }}
      style={{
        position: "fixed", inset: 0, zIndex: 200,
        background: "rgba(2,10,28,0.88)",
        backdropFilter: "blur(6px)",
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: "1rem",
        animation: "rrFadeIn 0.22s ease",
      }}
    >
      <div style={{
        background: C.navyMid, borderRadius: 2,
        border: "1px solid rgba(33,150,196,0.15)",
        width: "100%", maxWidth: 620,
        maxHeight: "90vh", overflowY: "auto",
        padding: "clamp(1.5rem, 4vw, 2.5rem)",
        position: "relative",
        animation: "rrSlideUp 0.28s cubic-bezier(.25,.46,.45,.94)",
      }}>
        {/* Close button */}
        <button
          onClick={onClose}
          style={{
            position: "absolute", top: 16, right: 16,
            background: "none", border: "1px solid rgba(255,255,255,0.12)",
            borderRadius: "50%", width: 32, height: 32,
            cursor: "pointer", color: "rgba(255,255,255,0.5)",
            fontSize: 16, display: "flex", alignItems: "center", justifyContent: "center",
            transition: "border-color 0.2s, color 0.2s",
          }}
          onMouseEnter={e => { e.currentTarget.style.borderColor = C.blue; e.currentTarget.style.color = C.blue; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.12)"; e.currentTarget.style.color = "rgba(255,255,255,0.5)"; }}
        >✕</button>

        {submitted ? (
          <div style={{ textAlign: "center", padding: "2rem 0" }}>
            <div style={{
              width: 52, height: 52, borderRadius: "50%",
              border: `1px solid ${C.blue}`,
              display: "flex", alignItems: "center", justifyContent: "center",
              margin: "0 auto 1.5rem",
            }}>
              <span style={{ color: C.blue, fontSize: 20 }}>✓</span>
            </div>
            <h3 style={{
              fontFamily: "'Cormorant Garamond', Georgia, serif",
              color: C.white, fontSize: "1.7rem", fontWeight: 500, margin: "0 0 0.75rem",
            }}>Request Received</h3>
            <p style={{
              color: "rgba(255,255,255,0.45)", fontSize: "0.9rem", lineHeight: 1.75,
              fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 300,
            }}>
              Someone from Refined Rentals will be in touch with your quote shortly.
            </p>
            <button onClick={onClose} style={{
              marginTop: "1.5rem", background: "none", border: `1px solid ${C.blue}`,
              color: C.blue, padding: "10px 28px", borderRadius: 1, cursor: "pointer",
              fontSize: 11, letterSpacing: "0.18em", textTransform: "uppercase",
              fontWeight: 600, fontFamily: "'DM Sans', system-ui, sans-serif",
            }}>Close</button>
          </div>
        ) : (
          <>
            {/* Header */}
            <div style={{ marginBottom: "1.75rem", paddingRight: 40 }}>
              <SectionLabel text="Quote Request" />
              <h2 style={{
                fontFamily: "'Cormorant Garamond', Georgia, serif",
                fontSize: "1.8rem", fontWeight: 500, color: C.white,
                margin: 0, lineHeight: 1.15,
              }}>Tell Us About Your Event</h2>
              {preselected && (
                <p style={{
                  color: C.blue, fontSize: "0.83rem", marginTop: "0.5rem",
                  fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 400,
                }}>
                  Requesting: <strong style={{ fontWeight: 600 }}>{preselected}</strong>
                </p>
              )}
            </div>

            {/* Name + Phone */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
              <input type="text" placeholder="Full Name *" value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                onFocus={fi} onBlur={fo} style={field} />
              <input type="tel" placeholder="Phone Number *" value={form.phone}
                onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}
                onFocus={fi} onBlur={fo} style={field} />
            </div>

            {/* Email */}
            <input type="email" placeholder="Email Address *" value={form.email}
              onChange={e => setForm(f => ({ ...f, email: e.target.value }))}
              onFocus={fi} onBlur={fo} style={{ ...field, marginBottom: 10 }} />

            {/* Event type + Location */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
              <input type="text" placeholder="Event Type (e.g. Wedding)" value={form.event}
                onChange={e => setForm(f => ({ ...f, event: e.target.value }))}
                onFocus={fi} onBlur={fo} style={field} />
              <input type="text" placeholder="Location (e.g. Maseru)" value={form.location}
                onChange={e => setForm(f => ({ ...f, location: e.target.value }))}
                onFocus={fi} onBlur={fo} style={field} />
            </div>

            {/* Date */}
            <input type="date" value={form.date}
              onChange={e => setForm(f => ({ ...f, date: e.target.value }))}
              onFocus={fi} onBlur={fo} style={{ ...field, marginBottom: 16 }} />

            {/* Services — constrained checkboxes */}
            <div style={{ marginBottom: 14 }}>
              <div style={{
                fontSize: 9, letterSpacing: "0.22em", textTransform: "uppercase",
                color: "rgba(255,255,255,0.3)", marginBottom: 9,
                fontFamily: "'DM Sans', system-ui, sans-serif",
              }}>Services Required</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                {KNOWN_SERVICES.map(s => {
                  const active = form.services.includes(s);
                  return (
                    <div key={s} onClick={() => toggleService(s)} style={{
                      display: "flex", alignItems: "center", gap: 9,
                      border: `1px solid ${active ? C.blue : "rgba(255,255,255,0.09)"}`,
                      background: active ? "rgba(33,150,196,0.1)" : "transparent",
                      borderRadius: 1, padding: "9px 11px", cursor: "pointer",
                      transition: "border-color 0.2s, background 0.2s",
                    }}>
                      <div style={{
                        width: 14, height: 14, borderRadius: 1, flexShrink: 0,
                        border: `1.5px solid ${active ? C.blue : "rgba(255,255,255,0.2)"}`,
                        background: active ? C.blue : "transparent",
                        display: "flex", alignItems: "center", justifyContent: "center",
                        transition: "all 0.2s",
                      }}>
                        {active && <span style={{ color: "white", fontSize: 9, fontWeight: 700 }}>✓</span>}
                      </div>
                      <span style={{
                        color: active ? "rgba(255,255,255,0.85)" : "rgba(255,255,255,0.45)",
                        fontSize: "0.8rem", fontFamily: "'DM Sans', system-ui, sans-serif",
                        fontWeight: 300, transition: "color 0.2s",
                      }}>{s}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Other / custom request */}
            <div style={{ marginBottom: 14 }}>
              <div style={{
                fontSize: 9, letterSpacing: "0.22em", textTransform: "uppercase",
                color: "rgba(255,255,255,0.3)", marginBottom: 6,
                fontFamily: "'DM Sans', system-ui, sans-serif",
              }}>Something Else in Mind?</div>
              <input
                type="text"
                placeholder="Describe what you need (e.g. stage, sound system, marquee...)"
                value={form.other}
                onChange={e => setForm(f => ({ ...f, other: e.target.value }))}
                onFocus={fi} onBlur={fo}
                style={{ ...field, marginBottom: 8 }}
              />
              {/* Disclaimer */}
              <div style={{
                background: "rgba(33,150,196,0.07)",
                border: "1px solid rgba(33,150,196,0.15)",
                borderRadius: 1, padding: "9px 12px",
                display: "flex", gap: 9, alignItems: "flex-start",
              }}>
                <span style={{ color: C.blue, fontSize: 12, flexShrink: 0, marginTop: 1 }}>ℹ</span>
                <p style={{
                  margin: 0, color: "rgba(255,255,255,0.38)",
                  fontSize: "0.78rem", lineHeight: 1.65,
                  fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 300,
                }}>
                  We welcome enquiries for items not on our standard list. Please note that{" "}
                  <strong style={{ color: "rgba(255,255,255,0.55)", fontWeight: 500 }}>
                    we will only provide a quote for services we are able to supply.
                  </strong>{" "}
                  We will let you know if we cannot accommodate a specific request.
                </p>
              </div>
            </div>

            {/* Message */}
            <textarea
              placeholder="Anything else we should know about your event..."
              value={form.message}
              onChange={e => setForm(f => ({ ...f, message: e.target.value }))}
              onFocus={fi} onBlur={fo}
              rows={3}
              style={{ ...field, resize: "vertical", marginBottom: 16 }}
            />

            {/* Submit */}
            <button onClick={handleSubmit} disabled={sending} style={{
              width: "100%", background: sending ? "rgba(33,150,196,0.45)" : C.blue,
              border: "none", borderRadius: 1, color: C.white,
              cursor: sending ? "wait" : "pointer", padding: "14px",
              fontSize: 11, letterSpacing: "0.2em", textTransform: "uppercase",
              fontWeight: 600, fontFamily: "'DM Sans', system-ui, sans-serif",
              transition: "background 0.25s",
            }}
              onMouseEnter={e => { if (!sending) e.currentTarget.style.background = C.blueLight; }}
              onMouseLeave={e => { if (!sending) e.currentTarget.style.background = C.blue; }}
            >{sending ? "Sending…" : "Submit Quote Request"}</button>

            <p style={{
              textAlign: "center", marginTop: 12, marginBottom: 0,
              color: "rgba(255,255,255,0.18)", fontSize: "0.75rem",
              fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 300,
            }}>
              We typically respond within one business day.
            </p>
          </>
        )}
      </div>
      <style>{`
        @keyframes rrFadeIn   { from { opacity: 0 } to { opacity: 1 } }
        @keyframes rrSlideUp  { from { opacity: 0; transform: translateY(20px) } to { opacity: 1; transform: translateY(0) } }
      `}</style>
    </div>
  );
}

/* ─── Navigation ─────────────────────────────────────────────── */
function Nav({ active, onQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", fn);
    return () => window.removeEventListener("scroll", fn);
  }, []);

  const go = (id) => {
    document.getElementById(id.toLowerCase())?.scrollIntoView({ behavior: "smooth" });
    setMenuOpen(false);
  };

  return (
    <nav style={{
      position: "fixed", inset: "0 0 auto 0", zIndex: 100,
      background: scrolled ? "rgba(3,17,46,0.96)" : "transparent",
      backdropFilter: scrolled ? "blur(14px)" : "none",
      borderBottom: scrolled ? "1px solid rgba(255,255,255,0.06)" : "none",
      transition: "background 0.45s, border-color 0.45s",
      padding: "0 clamp(1.25rem, 5vw, 4rem)",
    }}>
      <div style={{
        maxWidth: 1200, margin: "0 auto",
        display: "flex", alignItems: "center", justifyContent: "space-between", height: 70,
      }}>
        <button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
          style={{ background: "none", border: "none", cursor: "pointer", padding: 0, display: "flex", alignItems: "center", gap: 11 }}>
          <div style={{
            width: 36, height: 36, borderRadius: "50%",
            border: `1.5px solid ${C.blue}`,
            display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
          }}>
            <span style={{
              fontFamily: "'Cormorant Garamond', Georgia, serif",
              fontSize: 15, fontWeight: 600, color: C.blue, letterSpacing: "0.05em", lineHeight: 1,
            }}>rr</span>
          </div>
          <div style={{ textAlign: "left" }}>
            <div style={{
              fontFamily: "'Cormorant Garamond', Georgia, serif",
              fontSize: 17, fontWeight: 600, color: C.white, letterSpacing: "0.06em", lineHeight: 1.1,
            }}>Refined Rentals</div>
            <div style={{
              fontSize: 8.5, letterSpacing: "0.26em", textTransform: "uppercase",
              color: C.slateLight, fontFamily: "'DM Sans', system-ui, sans-serif",
              fontWeight: 400, opacity: 0.7,
            }}>Covering Every Occasion</div>
          </div>
        </button>

        <div className="rr-desktop-nav" style={{ display: "flex", alignItems: "center", gap: 32 }}>
          {NAV_LINKS.map(link => (
            <button key={link} onClick={() => go(link)} style={{
              background: "none", border: "none", cursor: "pointer", padding: 0,
              color: active === link.toLowerCase() ? C.blue : "rgba(255,255,255,0.62)",
              fontSize: 12, letterSpacing: "0.18em", textTransform: "uppercase",
              fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 500,
              transition: "color 0.25s",
            }}>{link}</button>
          ))}
          <button onClick={() => onQuote(null)} style={{
            background: "transparent", border: `1px solid ${C.blue}`, color: C.blue,
            cursor: "pointer", padding: "9px 22px", borderRadius: 1,
            fontSize: 11, letterSpacing: "0.2em", textTransform: "uppercase",
            fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 600,
            transition: "background 0.25s, color 0.25s",
          }}
            onMouseEnter={e => { e.currentTarget.style.background = C.blue; e.currentTarget.style.color = C.white; }}
            onMouseLeave={e => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.color = C.blue; }}
          >Get a Quote</button>
        </div>

        <button className="rr-hamburger" onClick={() => setMenuOpen(o => !o)}
          style={{ display: "none", background: "none", border: "none", cursor: "pointer", padding: 4, flexDirection: "column", gap: 5 }}>
          {[0,1,2].map(i => (
            <span key={i} style={{
              display: "block", width: 22, height: 1.5, background: C.white,
              transition: "transform 0.3s, opacity 0.3s",
              transform: menuOpen ? i===0 ? "rotate(45deg) translateY(6.5px)" : i===2 ? "rotate(-45deg) translateY(-6.5px)" : "none" : "none",
              opacity: menuOpen && i===1 ? 0 : 1,
            }} />
          ))}
        </button>
      </div>

      {menuOpen && (
        <div style={{ background: "rgba(3,17,46,0.98)", borderTop: "1px solid rgba(255,255,255,0.06)", padding: "1.5rem clamp(1.25rem, 5vw, 4rem) 2rem" }}>
          {[...NAV_LINKS, "Get a Quote"].map(link => (
            <button key={link}
              onClick={() => { if (link === "Get a Quote") { setMenuOpen(false); onQuote(null); } else go(link); }}
              style={{
                display: "block", width: "100%", textAlign: "left",
                background: "none", border: "none", cursor: "pointer",
                color: "rgba(255,255,255,0.75)", fontSize: 13, letterSpacing: "0.18em",
                textTransform: "uppercase", fontWeight: 500, padding: "13px 0",
                borderBottom: "1px solid rgba(255,255,255,0.06)",
                fontFamily: "'DM Sans', system-ui, sans-serif",
              }}
            >{link}</button>
          ))}
        </div>
      )}

      <style>{`
        @media (max-width: 780px) {
          .rr-desktop-nav { display: none !important; }
          .rr-hamburger   { display: flex !important; }
        }
        input[type="date"]::-webkit-calendar-picker-indicator { filter: invert(0.4); }
      `}</style>
    </nav>
  );
}

