/* ─── Gallery — real photos ──────────────────────────────────── */
function Gallery() {
  const [lightbox, setLightbox] = useState(null);

  // Close lightbox on Escape
  useEffect(() => {
    if (!lightbox) return;
    const fn = (e) => { if (e.key === "Escape") setLightbox(null); };
    window.addEventListener("keydown", fn);
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", fn); document.body.style.overflow = ""; };
  }, [lightbox]);

  return (
    <section id="gallery" style={{ background: C.offWhite, padding: "clamp(5rem, 9vw, 8rem) clamp(1.25rem, 5vw, 4rem)" }}>
      <div style={{ maxWidth: 1200, margin: "0 auto" }}>

        <Reveal style={{ marginBottom: "3.5rem" }}>
          <SectionLabel text="Our Work" />
          <h2 style={{
            fontFamily: "'Cormorant Garamond', Georgia, serif",
            fontSize: "clamp(2.1rem, 4vw, 3.25rem)", fontWeight: 500, color: C.navy,
            margin: "0 0 0.75rem", lineHeight: 1.12,
          }}>Equipment in Action</h2>
          <p style={{ color: C.slate, fontSize: "0.9rem", lineHeight: 1.7, margin: 0, maxWidth: 440, fontFamily: "'DM Sans', system-ui, sans-serif", fontWeight: 300 }}>
            A look at what we bring to the table — literally. Click any image to view it larger.
          </p>
        </Reveal>

        {/* 2-column editorial grid */}
        <div className="rr-gallery-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>

          {/* Left col: tent exterior (landscape) full width, toilet interior below */}
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <Reveal>
              <GalleryPhoto
                src={PHOTOS.tentExterior}
                label="Frame Tent — Outdoor Setup"
                aspect="56.25%"
                onClick={() => setLightbox({ src: PHOTOS.tentExterior, label: "Frame Tent — Outdoor Setup" })}
              />
            </Reveal>
            <Reveal delay={0.1}>
              <GalleryPhoto
                src={PHOTOS.toiletInterior}
                label="VIP Toilet — Interior Finish"
                aspect="100%"
                onClick={() => setLightbox({ src: PHOTOS.toiletInterior, label: "VIP Toilet — Interior Finish" })}
              />
            </Reveal>
          </div>

          {/* Right col: tent interior tall, toilet exterior below */}
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <Reveal delay={0.07}>
              <GalleryPhoto
                src={PHOTOS.tentInterior}
                label="Frame Tent — Interior Layout"
                aspect="130%"
                onClick={() => setLightbox({ src: PHOTOS.tentInterior, label: "Frame Tent — Interior Layout" })}
              />
            </Reveal>
            <Reveal delay={0.15}>
              <GalleryPhoto
                src={PHOTOS.toiletExterior}
                label="VIP Mobile Toilet Unit"
                aspect="75%"
                onClick={() => setLightbox({ src: PHOTOS.toiletExterior, label: "VIP Mobile Toilet Unit" })}
              />
            </Reveal>
          </div>
        </div>
      </div>

      {/* Lightbox */}
      {lightbox && (
        <div
          onClick={() => setLightbox(null)}
          style={{
            position: "fixed", inset: 0, zIndex: 300,
            background: "rgba(2,8,22,0.94)", backdropFilter: "blur(8px)",
            display: "flex", alignItems: "center", justifyContent: "center",
            padding: "2rem", cursor: "zoom-out",
            animation: "rrFadeIn 0.2s ease",
          }}
        >
          <div style={{ position: "relative", maxWidth: "90vw", maxHeight: "88vh" }}>
            <img
              src={lightbox.src}
              alt={lightbox.label}
              style={{ maxWidth: "90vw", maxHeight: "84vh", objectFit: "contain", borderRadius: 2, display: "block" }}
            />
            <div style={{
              position: "absolute", bottom: -32, left: 0,
              fontSize: 11, letterSpacing: "0.16em", textTransform: "uppercase",
              color: "rgba(255,255,255,0.4)", fontFamily: "'DM Sans', system-ui, sans-serif",
            }}>{lightbox.label}</div>
            <button onClick={() => setLightbox(null)} style={{
              position: "absolute", top: -40, right: 0,
              background: "none", border: "1px solid rgba(255,255,255,0.15)", borderRadius: "50%",
              width: 32, height: 32, cursor: "pointer", color: "rgba(255,255,255,0.6)",
              display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14,
            }}>✕</button>
          </div>
          <style>{`@keyframes rrFadeIn{from{opacity:0}to{opacity:1}}`}</style>
        </div>
      )}

      <style>{`
        @media(max-width:600px){
          .rr-gallery-grid{grid-template-columns:1fr!important}
        }
      `}</style>
    </section>
  );
}

function GalleryPhoto({ src, label, aspect, onClick }) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        position: "relative", borderRadius: 2, overflow: "hidden",
        paddingBottom: aspect, cursor: "zoom-in",
        background: C.navyMid,
      }}
    >
      <img
        src={src} alt={label}
        style={{
          position: "absolute", inset: 0, width: "100%", height: "100%",
          objectFit: "cover", display: "block",
          transform: hovered ? "scale(1.03)" : "scale(1)",
          transition: "transform 0.55s cubic-bezier(.25,.46,.45,.94)",
        }}
      />
      {/* Subtle overlay on hover */}
      <div style={{
        position: "absolute", inset: 0,
        background: "linear-gradient(to top, rgba(3,17,46,0.6) 0%, rgba(3,17,46,0.1) 50%, transparent 100%)",
        transition: "opacity 0.35s",
        opacity: hovered ? 1 : 0.55,
      }} />
      {/* Label */}
      <div style={{
        position: "absolute", bottom: 14, left: 16,
        fontSize: 9.5, letterSpacing: "0.2em", textTransform: "uppercase",
        color: "rgba(255,255,255,0.7)", fontFamily: "'DM Sans', system-ui, sans-serif",
        fontWeight: 400,
        transform: hovered ? "translateY(0)" : "translateY(4px)",
        opacity: hovered ? 1 : 0,
        transition: "transform 0.35s, opacity 0.35s",
      }}>{label}</div>
    </div>
  );
}

